// Des: Tests for report, backup, export and purge
// Flo: report holds no private text or paths > backup opens as a db > export is valid JSONL > purge keeps recent rows
// I/O: scratch state db and folder (no browser, no leaks)
// Run: zig build test -Dfile=ct-comm-misc-test.zig
// ===================================================================
const std = @import("std"); const misc = @import("ct-comm-misc.zig"); const task = @import("ru-task-runn.zig"); const stat = @import("st-stat-main.zig"); const pg = @import("ru-page-snap.zig"); const pace = @import("ru-huma-pace.zig"); const noti = @import("ru-noti-send.zig");
const allo = std.testing.allocator;
const Env = struct { sinkl: std.ArrayList(u8), tmpz: std.testing.TmpDir, dir: []u8, dbp: [:0]u8, sto: stat.Stat, aren: std.heap.ArenaAllocator, page: pg.Page, rng: pace.Rng,
fn up(self: *Env) !void { self.sinkl = .empty; self.tmpz = std.testing.tmpDir(.{}); self.dir = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{self.tmpz.sub_path}); self.dbp = try std.fmt.allocPrintSentinel(allo, "{s}/or-state.db", .{self.dir}, 0); self.sto = try stat.Stat.open(allo, self.dbp); self.aren = std.heap.ArenaAllocator.init(allo); self.rng = pace.Rng.init(1); }
fn down(self: *Env) void { self.aren.deinit(); self.sto.close(); allo.free(self.dbp); allo.free(self.dir); self.tmpz.cleanup(); }
fn ctx(self: *Env) task.Ctx { return .{ .gpaz = allo, .aren = self.aren.allocator(), .iozz = std.testing.io, .conf = .{}, .store = &self.sto, .mode = .live, .page = &self.page, .rng = &self.rng, .base = "", .statd = self.dir, .sink = &self.sinkl }; } };
test "report has no private text, no cookies, no folder paths" { var env: Env = undefined; try env.up(); defer env.down(); try env.sto.logAdd("post", "post|/|abcdef0123456789", true, 5); var cx = env.ctx(); var conf = cx.conf; conf.noti_chai_orde = &.{"file"}; cx.conf = conf; _ = noti.send(allo, std.testing.io, cx.aren, conf, env.dir, 9, "or needs you: log in"); const dir = try misc.report(&cx); const files = [_][]const u8{ "info.txt", "conf.json", "log.txt", "alerts.txt" }; for (files) |nm| { const pth = try std.fs.path.join(cx.aren, &.{ dir, nm }); const txt = try std.Io.Dir.cwd().readFileAlloc(std.testing.io, pth, cx.aren, .limited(1 << 16)); try std.testing.expect(std.mem.find(u8, txt, ".zz-base-home-tena") == null); try std.testing.expect(std.mem.find(u8, txt, "cookie") == null); } const lg = try std.Io.Dir.cwd().readFileAlloc(std.testing.io, try std.fs.path.join(cx.aren, &.{ dir, "log.txt" }), cx.aren, .limited(1 << 16)); try std.testing.expect(std.mem.find(u8, lg, "post|/|abcdef0123456789") != null); const al = try std.Io.Dir.cwd().readFileAlloc(std.testing.io, try std.fs.path.join(cx.aren, &.{ dir, "alerts.txt" }), cx.aren, .limited(1 << 16)); try std.testing.expect(std.mem.find(u8, al, "or needs you") != null); const info = try std.Io.Dir.cwd().readFileAlloc(std.testing.io, try std.fs.path.join(cx.aren, &.{ dir, "info.txt" }), cx.aren, .limited(1 << 16)); try std.testing.expect(std.mem.startsWith(u8, info, "or-orac-webs 0.1.0")); }
test "backup is a readable copy of the state db" { var env: Env = undefined; try env.up(); defer env.down(); try env.sto.logAdd("job", "Red bike", true, 1000); var cx = env.ctx(); cx.now_fix = 777; const dst = try misc.backup(&cx); try std.testing.expect(std.mem.endsWith(u8, dst, "or-state-777.db")); const dsz = try std.fmt.allocPrintSentinel(allo, "{s}", .{dst}, 0); defer allo.free(dsz); var cp = try stat.Stat.open(allo, dsz); defer cp.close(); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const rows = try cp.logRecent(aren.allocator(), 5); try std.testing.expectEqual(@as(usize, 1), rows.len); try std.testing.expectEqualStrings("Red bike", rows[0].what); }
test "export writes valid JSONL for the log" { var env: Env = undefined; try env.up(); defer env.down(); try env.sto.logAdd("job", "Red \"bike\"", true, 5); var cx = env.ctx(); try std.testing.expectEqual(@as(u32, 1), try misc.exportData(&cx)); const txt = try std.Io.Dir.cwd().readFileAlloc(std.testing.io, try std.fs.path.join(cx.aren, &.{ env.dir, "export", "log.jsonl" }), cx.aren, .limited(1 << 16)); const line = std.mem.trim(u8, txt, "\n"); const val = try std.json.parseFromSliceLeaky(std.json.Value, cx.aren, line, .{}); try std.testing.expectEqualStrings("Red \"bike\"", val.object.get("what").?.string); }
test "purge keeps recent rows and drops old ones" { var env: Env = undefined; try env.up(); defer env.down(); const dayz: i64 = 86400000; try env.sto.logAdd("post", "old", true, 1 * dayz); try env.sto.logAdd("post", "new", true, 90 * dayz); var cx = env.ctx(); cx.now_fix = 100 * dayz; try std.testing.expectEqual(@as(i64, 1), try misc.purgeRun(&cx)); const rows = try env.sto.logRecent(cx.aren, 10); try std.testing.expectEqual(@as(usize, 1), rows.len); try std.testing.expectEqualStrings("new", rows[0].what); }
